def backfill_published(entries):
    needs = sa.table(
        "needs", sa.column("id", sa.Integer), sa.column("office_id", sa.Integer),
        sa.column("published_by", sa.Integer), sa.column("published_at", sa.DateTime),
        sa.column("value_yen_month", sa.Integer), sa.column("rules_version", sa.String),
    )
    query = sa.select(needs).where(
        needs.c.published_by.is_not(None), needs.c.published_at.is_not(None)
    )
    connection = op.get_bind()
    previous = "0" * 64
    for row in connection.execute(query).mappings().all():
        payload = json.dumps(
            {
                "actor": row["published_by"],
                "at": row["published_at"].replace(tzinfo=UTC).isoformat(timespec="seconds"),
                "data": {"value_yen_month": row["value_yen_month"]},
                "kind": "published",
                "need": row["id"],
                "rules": row["rules_version"] or "1.0.0",
                "seq": 1,
            },
            ensure_ascii=False,
            separators=(",", ":"),
            sort_keys=True,
        )
        connection.execute(entries.insert().values(
            need_id=row["id"], office_id=row["office_id"], seq=1, kind="published",
            payload=payload, prev_hash=previous,
            entry_hash=sha256(f"{previous}\n{payload}".encode()).hexdigest(),
            actor_user_id=row["published_by"], created_at=row["published_at"],
        ))


